arguments.command:
cd /tmp/wt-ross && for b in rachel monica phoebe joey chandler ross; do
  git log origin/friend/$b --format='%H %ci %s' | grep -i friend;
done | sort -k2,3 | tail -40

cd /tmp/wt-ross && total=0; for b in rachel monica phoebe joey chandler ross; do
  n=$(git rev-list --count --grep='Friend-Message: 1' origin/friend/$b);
  total=$((total+n));
  echo "$b: $n";
done; echo "total: $total"

cd /tmp/wt-ross && for sha in d32d590511d59db4d10825951bb4546741e256e4 a1ed1ed65b0d327e43be2d11038d30444330a15d 19d728d019b47e54bf2b4add90b2bd631bd9a712 26b4686a19b87a9f9ac744c730b1ee585f63bce5 e7af26252e3a94740e7909b5c610c33e277eb08a; do
  echo "===== $sha =====";
  git log -1 --format='%cI' $sha;
  git show $sha --format='%B' --no-patch;
done
